import open from 'open';
/**
 * Error thrown when browser launch fails
 */ export class BrowserError extends Error {
    constructor(message){
        super(message);
        this.name = 'BrowserError';
    }
}
/**
 * Open a URL in the user's default browser
 *
 * Uses the `open` package for cross-platform browser launching
 *
 * @param url - URL to open in browser
 * @throws BrowserError if browser launch fails
 */ export async function openBrowser(url) {
    try {
        await open(url);
    } catch (error) {
        throw new BrowserError(`Failed to open browser: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
}
/**
 * Build OAuth authorization URL with all required parameters
 *
 * @param params - Authorization URL parameters
 * @returns Complete authorization URL
 */ export function buildAuthorizationUrl(params) {
    const url = new URL(params.authorizationUrl);
    url.searchParams.set('client_id', params.clientId);
    url.searchParams.set('redirect_uri', params.redirectUri);
    url.searchParams.set('response_type', 'code');
    url.searchParams.set('scope', params.scopes.join(' '));
    url.searchParams.set('state', params.state);
    url.searchParams.set('code_challenge', params.codeChallenge);
    url.searchParams.set('code_challenge_method', params.codeChallengeMethod);
    return url.toString();
}
